const r = JSON.parse($input.first().json.stdout);
const rpa = r.rpa || {estados: {}, cufes: 0, problemas: []};
const ocr = r.ocr || {};
const icono = {OK: '✅', PARCIAL: '⚠️', FALLA: '🔴'}[r.estado];
const lineas = [
  `${icono} RPA DIAN + OCR — ${r.estado} (${r.fecha})`,
  `RPA: ${rpa.estados.descargado || 0}/${rpa.cufes} PDF · captcha prom. ${rpa.seg_promedio_captcha} s`,
  `OCR: ${ocr.procesados_ok}/${ocr.archivos} facturas · ${ocr.items_totales} ítems · exactitud ${ocr.exactitud_media_vs_capa_texto_pct}%`,
  ...rpa.problemas.map(p => `• ${p.cufe} → ${p.estado}`),
  ...(ocr.revision || []).map(x => `• Revisar ${x.archivo}: ${x.motivo}`)
];
return [{ json: { estado: r.estado, mensaje: lineas.join('\n'), resumen: r } }];
